    h,w=len(grid),len(grid[0])
    from collections import Counter
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    allpts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]!=bg]
    cr=sum(r for r,c in allpts)/len(allpts); cc=sum(c for r,c in allpts)/len(allpts)
    out=[row[:] for row in grid]
    colors=set(grid[r][c] for r,c in allpts)
    for color in colors:
        pts={(r,c) for r in range(h) for c in range(w) if grid[r][c]==color}
        for dr,dc in ((1,1),(1,-1)):
            pairs=[(r,c) for r,c in pts if (r+dr,c+dc) in pts]
